sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float scale;
uniform float speed;
uniform float rise;
uniform float heightBias;
uniform float chromatic;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 p = coord / max(scale, 1.0);
    p.y += time * speed * rise;
    float n1 = vnoise(p * float2(1.0, 0.5) + float2(time * speed * 0.3, 0.0));
    float n2 = vnoise(p * 1.7 + 4.1);
    float2 off = (float2(n1, n2) - 0.5) * 2.0 * amount;
    off *= mix(1.0, smoothstep(0.0, 1.0, coord.y / size.y), heightBias);
    float4 cr = tex(coord + off * (1.0 + chromatic));
    float4 cg = tex(coord + off);
    float4 cb = tex(coord + off * (1.0 - chromatic));
    return fin(c, float4(cr.r, cg.g, cb.b, cg.a), opacity);
}
